function spawnEvent(){const tg={'':1,o:g.office>=0,m:!!partner(),k:kids().length>0,f:g.rel.some(r=>r.t=='fri'&&r.alive),p:fam().some(r=>r.role=='Mother'||r.role=='Father'),j:!!g.jail,w:!!g.job,sc:g.age<18};let pool=EV.filter(e=>g.age>=e[0]&&g.age<=e[1]&&tg[e[2]]&&(!!g.jail==(e[2]=='j')));const fr=pool.filter(e=>!g.seen.includes(e[3]));if(fr.length)pool=fr;if(!pool.length)return;const e=P(pool);g.seen.push(e[3]);g.event={x:e[3],c:e[4]}}
