const FAME=[['agent','Hire an agent',5,5000],['podcast','Appear on a podcast',5,0],['comm','Audition for a commercial',5,0],['tv','Give a TV interview',10,0],['spons','Seek a sponsorship deal',15,0],['cover','Pose for a magazine cover',20,0],['gala','Host a charity gala',30,25000],['memoir','Write a memoir',40,0]],FLIM={podcast:3,comm:2,tv:2,spons:1,cover:1,gala:1};
function fameV(){return `<div class=card><div class=t>${g.fm>=10?FT[tier()][0]:'Not famous yet'}</div>${Bar('Fame',g.fm,GOLD)}<p class=d>${g.fm<5?'Build fame through a special career or a big social media following, and these options open up.':'The more famous you are, the better these deals get.'} ${g.agent?'Your agent boosts your deals by 20%.':''}</p></div>`+FAME.map(([k,l,need,cost])=>B(`${l} <small>Needs fame ${need}${cost?'. Costs '+loc(pr(cost)):''}</small>`,`fameAct('${k}')`,g.fm<need||(cost>0&&g.cash<pr(cost))||(k=='agent'&&g.agent)||(FLIM[k]&&(g.mk['f'+k]||0)>=FLIM[k])||(k=='memoir'&&g.fl.memoir)||(k=='cover'&&g.looks<60))).join('')+(g.agent?B('Fire your agent',"g.agent=false;A({},'You parted ways with your agent.')"):'')}
function fameAct(k){const F=FAME.find(x=>x[0]==k);if(!F||g.fm<F[2])return;const c=pr(F[3]);if(c>0&&g.cash<c)return;if(FLIM[k]&&(g.mk['f'+k]||0)>=FLIM[k])return toast('You have done enough of that this year.');if(FLIM[k])g.mk['f'+k]=(g.mk['f'+k]||0)+1;const am=g.agent?1.2:1,bonus=g.agent?15:0;
 if(k=='agent'){g.agent=true;return A({m:-c,p:3},'You hired an agent. Your deals improve.')}
 if(k=='podcast')return A({fame:1,soc:R(100,2000),p:1},'You appeared on a podcast and gained followers.');
 if(k=='comm'){if(ch(cl(30+g.looks*.3+g.fm*.3+bonus,10,90))){const m=Math.round(pr(R(3000,8000))*(1+g.fm/50)*am);return A({m,fame:1,pop:1,p:2},`You starred in a commercial and earned ${fmt(m)}.`)}return A({p:-2},'You did not get the commercial.')}
 if(k=='tv'){if(ch(15))return A({fame:-2,pop:-4,p:-3},'You made an on-air gaffe and the internet noticed.');return A({fame:3,pop:3,p:2,soc:R(500,5000)},'Your TV interview was a hit.')}
 if(k=='spons'){if(ch(cl(25+g.fm*.5+bonus,10,90))){const m=Math.round(g.fm*pr(2500)*am);return A({m,pop:1,bl:1,p:2},`You signed a sponsorship deal worth ${fmt(m)}.`)}return A({p:-2},'No brand made an offer this time.')}
 if(k=='cover'){const m=Math.round(pr(10000)*am);return A({m,fame:3,pop:2,p:3},`Your magazine cover paid ${fmt(m)}.`)}
 if(k=='gala')return A({m:-c,pop:5,S:2,fame:2,p:4},'Your charity gala raised money and goodwill.');
 if(k=='memoir'){g.fl.memoir=1;const m=Math.round(g.fm*pr(15000)*am);return A({m,fame:4,p:4},`Your memoir became a bestseller, earning ${fmt(m)}.`)}}
